from unittest.mock import patch, mock_open
from main import start_timer, main

class TestPomodoroCLI(unittest.TestCase):
    @patch('main.time.sleep')
    def test_start_timer(self, mock_sleep):
        duration = 5
        start_timer(duration)
        mock_sleep.assert_called_with(1)

    @patch('main.load_session', return_value={})
    @patch('main.save_session')
    @patch('main.record_statistic')
    def test_main(self, mock_record_statistic, mock_save_session, mock_load_session):
        with patch('sys.argv', ['main.py', '--duration', '5']):
            main()
        mock_load_session.assert_called_once()
        mock_save_session.assert_called_once()
        mock_record_statistic.assert_called_once_with(5)

if __name__ == "__main__":
    unittest.main()
